## 0
1→//! Configuration contract: `config/observatory.example.toml` is the source of every default.
2→//!
3→//! Compiled to wasm for the UI (architecture I9), so nothing here depends on the platform
4→//! beyond `std::fs` and `std::env`, which only run when the shell asks for a file.
5→
6→use std::ffi::OsString;
7→use std::fmt;
8→use std::io;
9→use std::path::{Path, PathBuf};
10→
11→use serde::{Deserialize, Serialize};
12→
13→/// Environment variable that overrides the config file location.
14→pub const CONFIG_ENV: &str = "OBSERVATORY_CONFIG";
15→
16→/// Location below `$HOME` of the user's config file.
17→const DEFAULT_RELATIVE_PATH: &str = ".droid-observatory/config.toml";
18→
19→#[derive(Debug)]
20→pub enum ConfigError {
21→    Io {
22→        path: PathBuf,
23→        source: io::Error,
24→    },
25→    Parse {
26→        path: Option<PathBuf>,
27→        message: String,
28→    },
29→}
30→
31→impl fmt::Display for ConfigError {
32→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
33→        match self {
34→            Self::Io { path, source } => {
35→                write!(f, "cannot read config {}: {source}", path.display())
36→            }
37→            Self::Parse {
38→                path: Some(path),
39→                message,
40→            } => {
41→                write!(f, "invalid config {}: {message}", path.display())
42→            }
43→            Self::Parse {
44→                path: None,
45→                message,
46→            } => write!(f, "invalid config: {message}"),
47→        }
48→    }
49→}
50→
51→impl std::error::Error for ConfigError {
52→    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
53→        match self {
54→            Self::Io { source, .. } => Some(source),
55→            Self::Parse { .. } => None,
56→        }
57→    }
58→}
59→
