285→impl Config {
286→    pub fn from_toml_str(text: &str) -> Result<Self, ConfigError> {
287→        toml::from_str(text).map_err(|err| ConfigError::Parse {
288→            path: None,
289→            message: err.to_string(),
290→        })
291→    }
292→
293→    /// Loads `path` when given (a missing file is an error). Without a path, reads
294→    /// `$OBSERVATORY_CONFIG`, else `~/.droid-observatory/config.toml`; a missing default file
295→    /// means defaults.
296→    pub fn load(path: Option<&Path>) -> Result<Self, ConfigError> {
297→        Self::load_with(path, std::env::var_os(CONFIG_ENV), std::env::var_os("HOME"))
298→    }
299→
300→    fn load_with(
301→        explicit: Option<&Path>,
302→        env_override: Option<OsString>,
303→        home: Option<OsString>,
304→    ) -> Result<Self, ConfigError> {
305→        if let Some(path) = explicit {
306→            return Self::read_file(path);
307→        }
308→        let resolved = match (env_override, home) {
309→            (Some(path), _) if !path.is_empty() => PathBuf::from(path),
310→            (_, Some(home)) => Path::new(&home).join(DEFAULT_RELATIVE_PATH),
311→            _ => return Ok(Self::default()),
312→        };
313→        match Self::read_file(&resolved) {
314→            Err(ConfigError::Io { source, .. }) if source.kind() == io::ErrorKind::NotFound => {
315→                tracing::debug!(path = %resolved.display(), "no config file, using defaults");
316→                Ok(Self::default())
317→            }
318→            other => other,
319→        }
320→    }
321→
322→    fn read_file(path: &Path) -> Result<Self, ConfigError> {
323→        let text = std::fs::read_to_string(path).map_err(|source| ConfigError::Io {
324→            path: path.to_owned(),
325→            source,
326→        })?;
327→        toml::from_str(&text).map_err(|err| ConfigError::Parse {
328→            path: Some(path.to_owned()),
329→            message: err.to_string(),
330→        })
331→    }
332→}
