1→# droid-observatory configuration (example). Copy to ~/.droid-observatory/config.toml.
2→# Every value has a default and a reason (ai/RULES.md rule 4). Secrets never live here:
3→# they come from the OS keychain or the environment (see .env.example).
4→#
5→# Loaded by core::config (crates/observatory-core/src/config.rs). Config::default() equals
6→# this file; a test enforces it. Keys may be added by decision file, with their reason, in the
7→# same commit that reads them.
8→
9→[mission]
10→# Default models per role, mirrored in .factory/settings.json and the mission command
11→# (ai/RULES.md rule 19; docs/decisions/D-006). A change is a decision file.
12→orchestrator_model = "claude-fable-5.1"
13→worker_model = "claude-sonnet-5-5"
14→validator_model = "claude-opus-5-5"
15→# Branch the mission integrates into (PRD §2). "<name>" is the mission name.
16→branch_pattern = "mission/<name>"
17→
18→[ingest]
19→# Where Droid stores session transcripts. Read-only. Raw lines are never copied (PRD §11.2).
20→factory_sessions_dir = "~/.factory/sessions"
21→# Attach is the primary live mode (PRD §11.1, D-008): watch the sessions directory with a
22→# filesystem notifier and attach to every new session JSONL automatically. Off means attach
23→# only to files picked by hand.
24→watch_sessions_dir = true
25→# How often the attach/replay tailer re-reads a growing JSONL file, and the poll that backs
26→# the notifier when it coalesces or misses an event. 500 ms keeps "live within 1 s"
27→# (PRD FR-B6, M1 acceptance) with headroom and negligible IO.
28→jsonl_poll_ms = 500
29→# Upper bound on session files tailed at once, newest first. Bounds file handles and tail work;
30→# the UI reports how many sessions are not watched.
31→max_watched_sessions = 64
32→# Session files above this size are indexed but not tailed, with a warning, to protect memory.
33→max_session_file_mb = 512
34→# Size of one read per file per poll step. One bounded chunk per step keeps each step short
35→# enough for "live within 1 s" (PRD FR-B6) while a burst still drains over a few polls.
36→tail_chunk_kb = 1024
37→# Startup scan attaches only files modified within this window; older sessions stay in the
38→# library and open on demand, so a directory of hundreds of old sessions does not open at once.
39→startup_scan_hours = 24
40→
41→[ui]
42→# Shell-to-UI flush interval. 100 ms is well under the 1 s latency target and avoids one
43→# render per line during a burst.
44→event_batch_ms = 100
45→# Port of `trunk serve` for the browser host and `devUrl` of the Tauri shell. 3141 was free at
46→# planning; services.yaml and Trunk.toml carry the same number.
47→dev_port = 3141
48→
49→[store]
50→# SQLite index of events by pointer (path, byte offset, length). One index per user; raw lines
51→# stay where Droid wrote them and are never copied here (architecture I3).
52→path = "~/.droid-observatory/observatory.sqlite"
53→
54→[github]
55→# Poll interval for PR, checks and rulesets on the gate. 30 s stays well under GitHub's
56→# unauthenticated-equivalent budget for a single-user app and is fast enough for a human watching a gate.
57→poll_interval_s = 30
58→# App-level override of the merge policy read from branch protection/rulesets (PRD FR-G4).
59→# "auto" = read from GitHub; "human" = always require the Merge button; "policy" = never show it.
60→merge_policy = "auto"
61→# Branch a mission pull request targets. Parameterised so the demo pair (demo/base) and the
62→# real gate (main) use the same code path.
63→target_branch = "main"
64→# owner/repo the forge client reads. The default is this repository.
65→repo = "dctellya/droid-observatory"
66→
67→[intervention]
68→# A feature with no active time for this long raises the stall flag (PRD FR-H5).
69→# 20 minutes matches the troubleshooting examples in Factory's mission docs.
70→stall_threshold_min = 20
71→
72→[metrics]
73→# Price table used for cost when the stream does not expose credits (PRD §10.5).
74→# Dated file so every cost names the prices it used.
75→price_table = "config/prices/2026-10-22.toml"
76→# Mission overhead apportionment: "separate" (default, PRD §10.3) or "equal".
77→overhead_apportionment = "separate"
78→# Optional budget in the price table's currency; 0 disables the budget meter (PRD FR-M6).
79→budget = 0.0
80→
81→[telemetry]
82→# OTLP export of the app's own traces/metrics and of lane-9 mission metrics to Grafana Cloud
83→# (docs/decisions/D-004, contract in D-010). Off by default: the observatory must work fully
84→# offline. Also stays off, with a visible UI state, when the keychain item below is missing.
85→enabled = false
86→# Protocol Grafana Cloud's OTLP gateway accepts.
87→protocol = "http/protobuf"
88→# The owner's stack gateway (D-010). Not a secret. Signals go to /v1/metrics, /v1/traces, /v1/logs.
89→endpoint = "https://otlp-gateway-prod-eu-west-2.grafana.net/otlp"
90→# The Authorization header value ("Authorization=Basic ...") is read at runtime from the macOS
91→# keychain item with this service name and the current user as account. It is never written
92→# to config, the store or logs. No environment fallback in the app (CI uses B-002's secret).
93→keychain_service = "droid-observatory/otlp-headers"
94→# Value of the service.name resource attribute (D-010).
95→service_name = "droid-observatory"
96→# Resource attributes are fixed by D-010: service.name (above) and service.version (crate
97→# version, added by the app). No other resource attribute is sent.
98→# Metric export cadence. 15 s is Grafana Cloud's default scrape-equivalent and keeps
99→# the lane-9 budget meter near-live without flooding the gateway.
100→metric_export_interval_s = 15
101→# Attributes a metric may carry (D-010). Anything else is a bug: never session id, event id,
102→# feature id or free text.
103→metric_labels_allowed = ["mission", "milestone", "role", "model", "cause"]
104→# Active series the app may add on the stack (D-010). The spec states the computed number
105→# for the metric set below (BACKLOG B-017); the exporter refuses to start above it.
106→max_series = 200
107→# Lane-9 series to export (names are the contract; D-010). Counters and histograms only.
108→# Former per-attribute splits are now in the name (tokens by class, cost in USD).
109→mission_metrics = [
110→  "observatory.mission.cycle_seconds",
111→  "observatory.feature.cycle_seconds",
112→  "observatory.waste_seconds",
113→  "observatory.rework_windows",
114→  "observatory.fix_loops",
115→  "observatory.tokens.input",
116→  "observatory.tokens.output",
117→  "observatory.tokens.cache_read",
118→  "observatory.tokens.cache_write",
119→  "observatory.cost_usd",
120→  "observatory.unknown_events",
121→]
122→# Milestone label values allowed per metric: 7 milestones plus an "overflow" bucket, so the
123→# series count stays bounded when a mission defines more (D-010).
124→max_milestone_labels = 8
125→# Minimum gap before the exporter switches to another mission, so two missions are never
126→# active at once on the stack (D-010).
127→mission_switch_min_interval_min = 30
128→
129→[telemetry.buckets]
130→# Histogram bucket bounds in seconds for the mission cycle: hours to days.
131→mission_cycle_seconds = [3600, 7200, 14400, 28800, 86400, 172800]
132→# Histogram bucket bounds in seconds for a feature cycle: minutes to hours.
133→feature_cycle_seconds = [600, 1800, 3600, 7200, 14400]
134→
